// =============================================================================
// Module  : pcm_fifo
// Project : P6 PDM-to-PCM Audio Front End
// Purpose : Synchronous Circular PCM FIFO with Programmable IRQ Threshold
//           Stores 16-bit PCM audio samples generated by the decimation filter.
//           Provides full/empty/overflow status and threshold interrupt line.
// =============================================================================

`timescale 1ns / 1ps

module pcm_fifo #(
    parameter integer DATA_W   = 16,
    parameter integer ADDR_W   = 7,           // Depth = 2^7 = 128 words
    parameter integer THRESHOLD_DEFAULT = 64
)(
    input  wire                 clk,
    input  wire                 rst_n,

    // Write Port (from decimation filter)
    input  wire                 wr_en,
    input  wire [DATA_W-1:0]    wr_data,

    // Read Port (from APB bus / CPU)
    input  wire                 rd_en,
    output reg  [DATA_W-1:0]    rd_data,

    // Configuration & Status
    input  wire [ADDR_W:0]      irq_threshold, // Programmable IRQ water-level
    output wire [ADDR_W:0]      count,         // Number of words in FIFO
    output wire                 empty,
    output wire                 full,
    output reg                  overflow,
    output wire                 irq_threshold_hit
);

localparam integer DEPTH = (1 << ADDR_W);

// Dual-port RAM array
reg [DATA_W-1:0] mem [0:DEPTH-1];

reg [ADDR_W:0] wr_ptr;
reg [ADDR_W:0] rd_ptr;

// Word count is the difference between wr_ptr and rd_ptr
assign count = wr_ptr - rd_ptr;
assign empty = (wr_ptr == rd_ptr);
assign full  = (count == DEPTH);
assign irq_threshold_hit = (count >= irq_threshold);

// Write logic
always @(posedge clk) begin
    if (!rst_n) begin
        wr_ptr   <= {(ADDR_W+1){1'b0}};
        overflow <= 1'b0;
    end else begin
        if (wr_en) begin
            if (!full) begin
                mem[wr_ptr[ADDR_W-1:0]] <= wr_data;
                wr_ptr <= wr_ptr + 1'b1;
            end else begin
                overflow <= 1'b1; // Sticky overflow indicator
            end
        end
    end
end

// Read logic
always @(posedge clk) begin
    if (!rst_n) begin
        rd_ptr  <= {(ADDR_W+1){1'b0}};
        rd_data <= {DATA_W{1'b0}};
    end else begin
        if (rd_en && !empty) begin
            rd_data <= mem[rd_ptr[ADDR_W-1:0]];
            rd_ptr  <= rd_ptr + 1'b1;
        end
    end
end

// ── Formal Verification / Simulation Assertions ──────────────────────────────
`ifdef FORMAL
// Invariant 1: FIFO count can never exceed DEPTH
always @(posedge clk) begin
    if (rst_n) begin
        assert(count <= DEPTH);
        if (full)
            assert(!empty);
        if (empty)
            assert(count == 0);
    end
end

// Invariant 2: Safety property (no write when full)
always @(posedge clk) begin
    if (rst_n) begin
        if ($past(full) && $past(wr_en)) begin
            assert(overflow == 1'b1);
        end
    end
end
`endif

endmodule
